/** 三档手势落定后卡片往哪儿飞。 */
function flyVector(verdict: ReviewRating) {
  if (verdict === "good") return { x: 360, y: -24 };
  if (verdict === "again") return { x: -360, y: -24 };
  return { x: 0, y: -320 };
}

